input.command:
$root='C:\Users\eric_rash\Desktop\DEV'
$skip=@('.claude','_tools','_DRIVE','token-dashboard')
$dirs = @()
foreach ($p in @($root,"$root\Football","$root\SpecialRequests")) {
  if (Test-Path $p) { $dirs += Get-ChildItem -Directory -Force $p | ? { $skip -notcontains $_.Name -and $_.Name -notlike '*_OLD_merged*' -and $_.Name -ne '.git' } }
}
$rows=@()
foreach ($d in $dirs) {
  $f=$d.FullName
  if (-not (Test-Path "$f\.git")) {
    if ($d.FullName -eq "$root\Football" -or $d.FullName -eq "$root\SpecialRequests") { continue }
    $rows += "NOTREPO`t$f"; continue }
  $remote = git -C $f remote get-url origin 2>$null
  if (-not $remote) { $rows += "NOREMOTE`t$f"; continue }
  $unc = (git -C $f status --porcelain 2>$null | Measure-Object).Count
  $br = git -C $f rev-parse --abbrev-ref HEAD 2>$null
  $up = git -C $f rev-parse --abbrev-ref '@{u}' 2>$null
  $unp = if ($up) { git -C $f rev-list --count '@{u}..HEAD' 2>$null } else { 'noupstream' }
  $rows += "REPO`t$($d.Name)`t$br`tunc=$unc`tunp=$unp`t$remote"
}
$rows | Set-Content "$env:CLAUDE_JOB_DIR\tmp\inventory.tsv"
"total: $($rows.Count)"
$rows | ? { $_ -notmatch "unc=0`tunp=0`t" }
"--- local names"
($dirs | % Name) -join ','

