input.command:
$rows = Get-Content "$env:CLAUDE_JOB_DIR\tmp\inventory.tsv" | ? { $_ -like "REPO`t*" }
$root='C:\Users\eric_rash\Desktop\DEV'
$paths = @($root)
foreach ($r in $rows) { $n=($r -split "`t")[1]; foreach ($c in @("$root\$n","$root\Football\$n","$root\SpecialRequests\$n")) { if (Test-Path "$c\.git") { $paths += $c; break } } }
$paths = $paths | Select-Object -Unique
$out = $paths | ForEach-Object -Parallel {
  $f=$_
  $e = git -C $f fetch origin 2>&1 | Out-String
  $ok = $LASTEXITCODE
  $up = git -C $f rev-parse --abbrev-ref '@{u}' 2>$null
  if ($up) { $lr = git -C $f rev-list --left-right --count "HEAD...$up" 2>$null } else { $lr='noupstream' }
  "$f`tfetch=$ok`t$lr`t$($e.Trim() -replace '\s+',' ' | Select-Object -First 1)"
} -ThrottleLimit 12
$out | Set-Content "$env:CLAUDE_JOB_DIR\tmp\fetch.tsv"
"repos fetched: $($out.Count)"
$out | ? { $_ -notmatch "fetch=0`t0\s+0" }

