  $ahead,$behind = ($lr -split '\s+')
  $mh = Test-Path "$f\.git\MERGE_HEAD"
  [pscustomobject]@{f=$f;unc=$unc;ahead=$ahead;behind=$behind;merge=$mh}
} -ThrottleLimit 12
"checked: $($out.Count)"
